INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT145-S4-Q5$batch13$, 145, 4, 5, $batch13$Strengthen$batch13$, $batch13$Some scientific issues are so complex and counterintuitive that they cannot be well understood by readers of popular magazines. Nonetheless, stories about these difficult scientific issues are frequently the ones that these readers would find most fascinating. Unfortunately, this means that some of the scientific stories that would be most interesting to readers are usually not covered in popular magazines since _______.$batch13$, $batch13$The conclusion of the argument is strongly supported if which one of the following completes the passage?$batch13$, $batch13$A$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=145 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q5$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$editors of popular magazines generally do not approve stories about issues that cannot be well understood by those magazines’ readers$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$popular magazines cannot stay in business unless they regularly publish stories that their readers find interesting$batch13$, $batch13$Opposite$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$highly complex and counterintuitive theories are increasingly common in almost all branches of science$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$readers of popular magazines are generally unable to accurately assess their own understanding of complex scientific issues$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$most readers of popular magazines are unwilling to seek out other sources in order to read about scientific issues that they find interesting$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$Some of the science stories readers would find most interesting usually aren't covered in popular magazines.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Some scientific issues are too complex for popular-magazine readers to understand well. Stories about those issues are often the ones readers would find most fascinating.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$The blank explains why the stories go uncovered. The premises say readers can't understand these issues. The missing link is that magazines skip stories their readers can't understand.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Magazines don't run stories their readers can't understand.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT145-S4-Q5$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Editors reject stories readers can't understand, so the complex stories don't get covered.$batch13$), ($batch13$B$batch13$, $batch13$If magazines need interesting stories, they'd want to cover these.$batch13$), ($batch13$C$batch13$, $batch13$Complex theories becoming common doesn't explain why magazines skip them.$batch13$), ($batch13$D$batch13$, $batch13$Readers misjudging their understanding doesn't explain editors' choices.$batch13$), ($batch13$E$batch13$, $batch13$Whether readers look elsewhere doesn't explain what magazines cover.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT145-S4-Q5$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
